export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };
}

input.new_string:
export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  // Apply thresholds if provided
  if (Object.keys(thresholds).length > 0) {
    const thresholdResults = [];
    let allPassed = true;

    for (const [metricId, minValue] of Object.entries(thresholds)) {
      // Find the metric
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score ?? null;
      const passed = score !== null && score !== undefined && score >= minValue;

      if (!passed) {
        allPassed = false;
      }

      thresholdResults.push({
        metric: metricId,
        min: minValue,
        score,
        passed
      });
    }

    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

