function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  // Parse and validate thresholds
  let parsedThresholds: Record<string, number> = {};
  if (options.threshold && options.threshold.length > 0) {
    const validMetricIds = new Set(evaluations.map((m: any) => m.id));

    for (const thresholdStr of options.threshold) {
      // Parse format: metric=value
      const parts = thresholdStr.split('=');
      if (parts.length !== 2) {
        log.error('Invalid threshold format. Use: --threshold <metric>=<number>', {
          received: thresholdStr,
          format: '<metric>=<number>'
        });
        process.exit(2);
      }

      const [metricId, valueStr] = parts;
      const value = Number.parseFloat(valueStr);

      // Validate metric id exists
      if (!validMetricIds.has(metricId)) {
        log.error('Unknown metric in threshold.', {
          metric: metricId,
          validMetrics: Array.from(validMetricIds)
        });
        process.exit(2);
      }

      // Validate value is a number
      if (Number.isNaN(value)) {
        log.error('Threshold value must be a number.', {
          received: valueStr,
          metric: metricId
        });
        process.exit(2);
      }

      // Validate value is in range [0, 1]
      if (value < 0 || value > 1) {
        log.error('Threshold value must be between 0 and 1.', {
          received: value,
          metric: metricId
        });
        process.exit(2);
      }

      parsedThresholds[metricId] = value;
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds: parsedThresholds
  });

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Exit with appropriate code based on threshold results
  if (report.passed === false) {
    process.exit(1);
  }
}

