62	export function generateReport({
63	  evaluations,
64	  outputsPath,
65	  referencesPath,
66	  generatedAt = new Date().toISOString(),
67	  thresholds = {}
68	} = {}) {
69	  const totalSamples = evaluations.reduce((total, metric) => {
70	    if (typeof metric.total === 'number') return Math.max(total, metric.total);
71	    return total;
72	  }, 0);
73	
74	  const report = {
75	    metadata: {
76	      generatedAt,
77	      outputsPath,
78	      referencesPath,
79	      totalSamples
80	    },
81	    metrics: evaluations
82	  };
83	
84	  // Apply thresholds if provided
85	  if (Object.keys(thresholds).length > 0) {
86	    const thresholdResults = [];
87	    let allPassed = true;
88	
89	    for (const [metricId, minValue] of Object.entries(thresholds)) {
90	      // Find the metric
91	      const metric = evaluations.find((m) => m.id === metricId);
92	      const score = metric?.score ?? null;
93	      const passed = score !== null && score !== undefined && score >= minValue;
94	
95	      if (!passed) {
96	        allPassed = false;
97	      }
98	
99	      thresholdResults.push({
100	        metric: metricId,
101	        min: minValue,
102	        score,
103	        passed
104	      });
105	    }
106	
107	    report.passed = allPassed;
108	    report.thresholds = thresholdResults;
109	  }
110	
111	  return report;

